 * @example getSystemMenuItems({ setView, ... })[0].key => 'docs'
 ***/
export function getSystemMenuItems({
  setIsOpen,
  setIsSystemGuideOpen,
  setIsCustomizationModalOpen,
  setIsShortcutsModalOpen,
  setView,
} = {}) {
  const close = () => setIsOpen?.(false);
