  const openDocsView = () => {
    close();
    setView?.('docs');
  };
  return [
    {
      key: 'docs',
      icon: '📚',
      label: 'Docs',
      desc: 'Platform guides — not project-specific',
      shortcut: 'D',
      onClick: openDocsView,
    },
    {
      key: 'compact-monitor',
      icon: '📡',
